func (r *mutationResolver) VendorUpload(ctx context.Context, files []*graphql.Upload, input *model.ProductInput) (*model.Product, error) {
	// Retrieve the VendorID from the context
	VendorIDStr, err := r.Query().GetID(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to get vendor ID: %v", err)
	}

	// Convert VendorID from string to uuid.UUID
	VendorID, err := uuid.Parse(*VendorIDStr)
	if err != nil {
		return nil, fmt.Errorf("invalid vendor ID format: %v", err)
	}

	bucketName := fmt.Sprintf("vendor-%s-bucket", VendorID)

	var productURLs []string

	// Loop through the files and handle each one
	for _, file := range files {
		// Generate a unique ID for the file
		uniqueID := uuid.New().String()
		fileName := fmt.Sprintf("%s-%s", uniqueID, file.Filename)

		// Create a reader for the file
		fileReader := file.File

		// Upload the file to MinIO
		_, err := r.MinIOClient.PutObject(ctx, bucketName, fileName, fileReader, file.Size, minio.PutObjectOptions{ContentType: file.ContentType})
		if err != nil {
			return nil, fmt.Errorf("failed to upload file %s: %v", file.Filename, err)
		}

		// Generate a URL for the file

		fileURL := fmt.Sprintf("/minio/%s/%s", bucketName, fileName)

		// Append the file URL to the product URLs list
		productURLs = append(productURLs, fileURL)
	}
	// some := "some"
	// Create a new product with the provided details
	product := model.Product{
		Name:              &input.Name,             // Replace with actual product name if available
		Price:             &input.Price,            // Replace with actual price if available
		State:             (*string)(&input.State), // Replace with actual state if available
		Title:             &input.Title,            // Replace with actual title if available
		Brand:             &input.Brand,            // Replace with actual brand if available
		ImageUrls:         productURLs,
		VendorsBucketName: &bucketName,
		VendorID:          VendorID,
	}

	// Save the new product to the database
	if err := r.DB.Create(&product).Error; err != nil {
		return nil, fmt.Errorf("failed to save product: %v", err)
	}

	// Return the created product
	return &product, nil
}

